{"kind":"tool","id":"ICuHTBaDWwM","toolName":"write_file","input":{"path":"src/components/shell/header.tsx","instructions":"Create header bar with channel switcher, theme badge, and profile menu","content":""use client";

import { useEffect, useRef, useState } from "react";
import {
  ChevronDown,
  Menu,
  Moon,
  Search,
  User,
  LogOut,
  ChevronsUpDown,
} from "lucide-react";
import { cn } from "@/lib/utils";

const CHANNELS = [
  { id: "ch-1", name: "Forgevyn Main" },
  { id: "ch-2", name: "Forgevyn Clips" },
  { id: "ch-3", name: "Partner Highlights" },
];

type HeaderProps = {
  onMenuClick: () => void;
};

export function Header({ onMenuClick }: HeaderProps) {
  const [channelOpen, setChannelOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [channel, setChannel] = useState(CHANNELS[0]);

  const channelRef = useRef<HTMLDivElement>(null);
  const profileRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function onPointerDown(event: MouseEvent) {
      if (
        channelRef.current &&
        !channelRef.current.contains(event.target as Node)
      ) {
        setChannelOpen(false);
      }
      if (
        profileRef.current &&
        !profileRef.current.contains(event.target as Node)
      ) {
        setProfileOpen(false);
      }
    }
    document.addEventListener("mousedown", onPointerDown);
    return () => document.removeEventListener("mousedown", onPointerDown);
  }, []);

  return (
    <header className="sticky top-0 z-20 flex h-16 items-center gap-3 border-b border-zinc-800 bg-zinc-950/85 px-4 backdrop-blur-md sm:px-6">
      <button
        type="button"
        onClick={onMenuClick}
        aria-label="Open navigation"
        className="rounded-md p-2 text-zinc-400 transition-colors hover:bg-zinc-800 hover:text-zinc-100 lg:hidden"
      >
        <Menu className="h-5 w-5" aria-hidden />
      </button>

      {/* Channel switcher (placeholder) */}
      <div className="relative" ref={channelRef}>
        <button
          type="button"
          onClick={() => {
            setChannelOpen((v) => !v);
            setProfileOpen(false);
          }}
          aria-haspopup="menu"
          aria-expanded={channelOpen}
          className="flex items-center gap-2 rounded-lg border border-zinc-800 bg-zinc-900/70 px-3 py-2 text-sm text-zinc-200 transition-colors hover:border-zinc-700 hover:bg-zinc-900"
        >
          <span className="h-2 w-2 rounded-full bg-emerald-500" aria-hidden />
          <span className="max-w-32 truncate sm:max-w-56">
            {channel.name}
          </span>
          <ChevronDown
            className={cn(
              "h-4 w-4 text-zinc-500 transition-transform",
              channelOpen && "rotate-180"
            )}
            aria-hidden
          />
        </button>

        {channelOpen && (
          <div
            role="menu"
            className="absolute left-0 top-full z-30 mt-2 w-60 overflow-hidden rounded-lg border border-zinc-800 bg-zinc-900 p-1 shadow-xl shadow-black/40"
          >
            <p className="px-3 py-2 text-xs font-medium uppercase tracking-wide text-zinc-500">
              Switch channel
            </p>
            {CHANNELS.map((item) => (
              <button
                key={item.id}
                type="button"
                role="menuitem"
                onClick={() => {
                  setChannel(item);
                  setChannelOpen(false);
                }}
                className={cn(
                  "flex w-full items-center gap-2 rounded-md px-3 py-2 text-left text-sm transition-colors",
                  item.id === channel.id
                    ? "bg-violet-600/15 text-violet-300"
                    : "text-zinc-300 hover:bg-zinc-800"
                )}
              >
                {item.name}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Search placeholder */}
      <div className="hidden flex-1 items-center gap-2 rounded-lg border border-zinc-800 bg-zinc-900/60 px-3 py-2 md:flex">
        <Search className="h-4 w-4 text-zinc-500" aria-hidden />
        <input
