+import { createServerClient } from "@supabase/ssr";
+import { NextResponse, type NextRequest } from "next/server";
+
+/**
+ * Refreshes the Supabase auth session cookies on every matched request.
+ *
+ * Returns a NextResponse that carries any updated auth cookies (and the
+ * no-store cache headers Supabase requires) back to the browser.
+ * Wired up from `src/proxy.ts` (Next.js 16's middleware entry point).
+ */
+export async function updateSession(request: NextRequest) {
+  const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
+  const anonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
+
+  if (!url || !anonKey) {
+    // Never throw inside the proxy: a missing env var would blank the app.
+    console.error(
+      "[supabase] Missing NEXT_PUBLIC_SUPABASE_URL or NEXT_PUBLIC_SUPABASE_ANON_KEY; skipping session refresh."
+    );
+    return NextResponse.next({ request });
+  }
+
+  let response = NextResponse.next({ request });
+
+  const supabase = createServerClient(url, anonKey, {
+    cookies: {
+      getAll() {
+        return request.cookies.getAll();
+      },
+      setAll(cookiesToSet) {
+        cookiesToSet.forEach(({ name, value }) =>
+          request.cookies.set(name, value)
+        );
+        response = NextResponse.next({ request });
+        cookiesToSet.forEach(({ name, value, options }) =>
+          response.cookies.set(name, value, options)
+        );
+      },
+    },
+  });
+
+  // Trigger lazy session init / refresh before route code runs.
+  // getClaims() loads (and refreshes when expired) the session from cookies,
+  // writing any rotated tokens back through setAll above.
+  await supabase.auth.getClaims();
+
+  return response;
+}
