export async function checkChannelEmailOwnership(email: string): Promise<EmailOwnershipCheck> {
  const normalized = email.trim().toLowerCase();
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!re.test(normalized)) return { ok:false, reason:"Enter a valid email address." };
  const domain = normalized.split("@")[1];
  try {
    const res = await fetch(`https://dns.google/resolve?name=${encodeURIComponent(domain)}&type=MX`);
    if (!res.ok) return { ok:false, reason:"Could not verify the email domain (DNS lookup failed)." };
    const data = await res.json() as { Answer?: { type: number }[] };
    const hasMx = Array.isArray(data.Answer) && data.Answer.some(a => a.type === 15);
    if (!hasMx) return { ok:false, reason:`${domain} has no MX record — it cannot receive ownership emails.` };
    return { ok:true, reason:`${domain} accepts email (MX record found). Ownership email can be delivered.` };
  } catch { return { ok:false, reason:"Network error while checking the domain." }; }
}
