{"kind":"tool","id":"IHUfuvJBH9Y","toolName":"write_file","input":{"path":"src/store/workspace.ts","instructions":"Create Zustand store for channels and active channel state","content":"import { create } from "zustand";
import { createClient } from "@/lib/supabase/client";
import type { Channel } from "@/types/database";

type WorkspaceState = {
  /** Channels owned by the signed-in user. */
  channels: Channel[];
  /** `null` = "All channels" (no filter). */
  activeChannelId: string | null;
  channelsLoading: boolean;
  channelsError: string | null;
  loadChannels: (options?: { force?: boolean }) => Promise<void>;
  setChannels: (channels: Channel[]) => void;
  setActiveChannel: (channelId: string | null) => void;
};

export const useWorkspaceStore = create<WorkspaceState>((set, get) => ({
  channels: [],
  activeChannelId: null,
  channelsLoading: false,
  channelsError: null,

  setChannels: (channels) => set({ channels, channelsError: null }),

  setActiveChannel: (channelId) => set({ activeChannelId: channelId }),

  loadChannels: async ({ force = false } = {}) => {
    const { channelsLoading, channels } = get();
    if (channelsLoading) return;
    if (!force && channels.length > 0) return;

    set({ channelsLoading: true, channelsError: null });

    try {
      const supabase = createClient();
      const {
        data: { user },
      } = await supabase.auth.getUser();

      if (!user) {
        set({ channels: [], channelsLoading: false, channelsError: null });
        return;
      }

      // RLS already scopes rows to the owner; filter again as defense in depth.
      const { data, error } = await supabase
        .from("channels")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);

      const channels = (data ?? []) as Channel[];
      const active = get().activeChannelId;
      set({
        channels,
        channelsLoading: false,
        channelsError: null,
        // Drop a selected channel that no longer exists.
        activeChannelId:
          active && !channels.some((c) => c.id === active) ? null : active,
      });
    } catch (err) {
      set({
        channelsLoading: false,
        channelsError:
          err instanceof Error ? err.message : "Failed to load channels.",
      });
    }
  },
}));
"}}
{"kind":"tool","id":"IHUx8FCby78","toolName":"write_file","input":{"path":"src/lib/channel-email-check.ts","instructions":"Add channel email ownership check helper","content":"export type OwnershipCheckResult = {
  ok: boolean;
  reason: string;
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Channel email ownership check.
 *
 * Verifies that the supplied mailbox is syntactically valid and that its
 * domain publishes an MX record, i.e. it can actually receive the ownership
 * email we would send. Uses public DNS-over-HTTPS, so it has no side effects.
 */
export async function checkChannelEmailOwnership(
  email: string
): Promise<OwnershipCheckResult> {
  const normalized = email.trim().toLowerCase();

  if (!EMAIL_PATTERN.test(normalized)) {
    return { ok: false, reason: "Enter a valid email address." };
  }

  const domain = normalized.split("@")[1];
  if (!domain) {
    return { ok: false, reason: "Enter a valid email address." };
  }

  try {
    const response = await fetch(
      `https://dns.google/resolve?name=${encodeURIComponent(domain)}&type=MX`,
      { headers: { accept: "application/dns-json" } }
    );

    if (!response.ok) {
      return {
        ok: false,
        reason: "Could not verify the domain (DNS lookup failed).",
      };
    }

    const payload = (await response.json()) as {
      Answer?: Array<{ type: number }>;
      Status?: number;
    };

    const hasMx = Array.isArray(payload.Answer)
      ? payload.Answer.some((record) => record.type === 15)
      : false;

    if (!hasMx) {
      return {
        ok: false,
        reason: `${domain} has no MX record, so it cannot receive an ownership email.`,
      };
    }

    return {
      ok: true,
      reason: `${domain} accepts email (MX record found) — ownership email can be delivered.`,
    };
  } catch {
    return {
      ok: false,
      reason: "Network error while checking the domain. Try again.",
    };
  }
}
"}}


