Let me update `loadVideo`'s metadata handler:

```ts
el.addEventListener("loadedmetadata", () => {
  if (get().videoEl !== el) return;
  if (Number.isFinite(el.duration) && el.duration > 0) {
    set({ duration: el.duration, trimStart: 0, trimEnd: el.duration, currentTime: 0 });
    return;
  }
  // Some WebM files (e.g. MediaRecorder recordings) omit duration metadata.
  // Seeking far past the end forces the browser to resolve it.
  const resolveDuration = () => {
    if (get().videoEl !== el) return;
    if (Number.isFinite(el.duration) && el.duration > 0) {
      el.removeEventListener("durationchange", resolveDuration);
      el.currentTime = 0;
      set({ duration: el.duration, trimStart: 0, trimEnd: el.duration, currentTime: 0 });
    }
  };
  el.addEventListener("durationchange", resolveDuration);
  el.currentTime = 1e101;
});
```

